#!/usr/bin/env bash
#
# apptainer / run_apptainer.sh
# ---------------------------------------------------------------------------- #
#
# Author : Aditya Marathe
# Email  : aditya.marathe.20@ucl.ac.uk
#
# ---------------------------------------------------------------------------- #
#
# This script was generated by Claude and checked by a human.
#
# Usage
# -----
#   bash ~/oscana/apptainer/run_apptainer.sh
#   bash ~/oscana/apptainer/run_apptainer.sh python <script>.py <args>
#

set -euo pipefail

# =============================== [ Constants ] ============================== #

PROJECT_NAME="oscana"
REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="$REPO_DIR/.env"
DATA_DIR="/unix/nova3/minos"
RUNS_DIR="$HOME/$PROJECT_NAME-runs"

APPTAINER_AREA="/unix/nova3/minos/sing/$USER/$PROJECT_NAME"
IMAGE="$APPTAINER_AREA/$PROJECT_NAME.sif"

# ================================= [ Checks ] =============================== #

if [[ ! -f "$REPO_DIR/apptainer/$PROJECT_NAME.def" ]]; then
    echo "Error: '$PROJECT_NAME' repository not found at '$REPO_DIR'." >&2
    exit 1
fi

if [[ ! -d "$DATA_DIR" ]]; then
    echo "Error: data directory '$DATA_DIR' does not exist." >&2
    exit 1
fi

# For older versions of Apptainer...
APPTAINER="$(command -v apptainer || command -v singularity || true)"
if [[ -z "$APPTAINER" ]]; then
    echo "Error: neither 'apptainer' nor 'singularity' was found." >&2
    exit 1
fi

# Create a placeholder ".env" file
if [[ ! -f "$ENV_FILE" ]]; then
    echo "OSCANA_PLACEHOLDER=1" > "$ENV_FILE"
fi

# Chris' suggestion...
export APPTAINER_CACHEDIR="$APPTAINER_AREA/.apptainer"
export APPTAINER_TMPDIR="$APPTAINER_AREA/tmp"
export SINGULARITY_CACHEDIR="$APPTAINER_CACHEDIR"
export SINGULARITY_TMPDIR="$APPTAINER_TMPDIR"

mkdir -p "$APPTAINER_CACHEDIR" "$APPTAINER_TMPDIR"
mkdir -p "$RUNS_DIR"

# ================================= [ Build ] ================================ #

# Note: The image only holds the dependencies, as the repository is mounted
#       over `/app` at runtime (so code edits apply without a rebuild). We
#       only rebuild if the definition file or the dependencies have changed.

cd "$REPO_DIR"
def_file="apptainer/$PROJECT_NAME.def"
deps=("$def_file" pyproject.toml poetry.lock)
if [[ ! -f "$IMAGE" ]] ||
    [[ -n "$(find "${deps[@]}" -newer "$IMAGE" -print -quit)" ]]; then
    tmp_image="$APPTAINER_AREA/.build-$$.sif"
    "$APPTAINER" build --force --fakeroot "$tmp_image" "$def_file"
    mv "$tmp_image" "$IMAGE"
fi

# ================================== [ Run ] ================================= #

"$APPTAINER" exec \
    --cleanenv \
    --bind "$REPO_DIR:/app" \
    --bind "$RUNS_DIR:/work" \
    --bind "$DATA_DIR:$DATA_DIR:ro" \
    --pwd /work \
    "$IMAGE" \
    "${@:-bash}"
